using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.IO.Compression;
namespace ContourWatch {
 public static class DiagnosticReport {
  static readonly object Gate=new object();static readonly Dictionary<string,object> Collectors=new Dictionary<string,object>();static readonly Dictionary<string,string> States=new Dictionary<string,string>();
  static readonly string[] DetailKeys={"reason","message","errorType","pawnIoInstalled","smartctlExit","wearSource","sensorType","hardwareType"};
  public static void Record(string collector,List<Dictionary<string,object>> metrics,long elapsed){lock(Gate){try{
   var projected=new List<object>();foreach(var m in metrics.Take(128)){
    var details=new Dictionary<string,object>();object raw;if(m.TryGetValue("details",out raw)){var map=raw as Dictionary<string,object>;if(map!=null){foreach(string key in DetailKeys)if(map.ContainsKey(key)&&map[key]!=null)details[key]=map[key] is bool||map[key] is int||map[key] is long?map[key]:(object)AgentLog.Clean(Convert.ToString(map[key]));}else if(raw is string)details["reason"]=AgentLog.Clean((string)raw);}
    string state=Agent.Get(m,"state"),id=AgentLog.Clean(Agent.Get(m,"id")),reason=Agent.Get(details,"reason",Agent.Get(details,"message",Agent.Get(details,"errorType",state=="ok"?"Показатель получен":"Источник не предоставил значение; проверьте драйвер, поддержку датчика и права службы")));
    var safe=Agent.Obj("id",id,"kind",AgentLog.Clean(Agent.Get(m,"kind")),"name",AgentLog.Clean(Agent.Get(m,"name")),"source",AgentLog.Clean(Agent.Get(m,"source")),"state",state,"measuredAt",Agent.Get(m,"measuredAt"),"reason",reason,"details",details);projected.Add(safe);
    string metricKey=collector+":"+id,signature=state+":"+reason,old;if(!States.TryGetValue(metricKey,out old)||old!=signature){States[metricKey]=signature;AgentLog.Write(state=="ok"?"info":"warning","collector."+collector,"metric.state",reason,"collector",collector,"metricId",id,"metricName",Agent.Get(m,"name"),"source",Agent.Get(m,"source"),"state",state,"elapsedMs",elapsed);}
   }
   if(metrics.Count==0)AgentLog.Write("warning","collector."+collector,"collector.empty","Сборщик вернул пустой список показателей","collector",collector,"elapsedMs",elapsed);
   Collectors[collector]=Agent.Obj("completedAt",Agent.Iso(),"elapsedMs",elapsed,"metricCount",metrics.Count,"truncated",metrics.Count>128,"metrics",projected);
   string directory=Path.Combine(Agent.Root,"public");Directory.CreateDirectory(directory);Agent.Atomic(Path.Combine(directory,"diagnostics.json"),Agent.Json.Serialize(Agent.Obj("version",Agent.Version,"updatedAt",Agent.Iso(),"runtime",Environment.Version.ToString(),"architecture",Environment.Is64BitProcess?"x64":"x86","collectors",Collectors)));
  }catch(Exception e){AgentLog.Write("warning","diagnostics","snapshot.failed",e.GetType().Name);}}}
  public static string ReadBounded(string path,int max){using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(stream.Length>max)stream.Seek(-max,SeekOrigin.End);using(var reader=new StreamReader(stream,Encoding.UTF8)){if(stream.Position>0)reader.ReadLine();return reader.ReadToEnd();}}}
  public static string Text(string root){var text=new StringBuilder();text.AppendLine("Контур · логи и диагностика");text.AppendLine("Экспорт: "+Agent.Iso());text.AppendLine("Время записей указано в UTC. Данные могут быть устаревшими, если служба остановлена или сбор приостановлен.");
   string directory=Path.Combine(root,"public"),snapshot=Path.Combine(directory,"diagnostics.json");try{var report=Agent.Json.Deserialize<Dictionary<string,object>>(ReadBounded(snapshot,900000));text.AppendLine("Версия: "+Agent.Get(report,"version")+" · Последнее обновление: "+Agent.Get(report,"updatedAt"));var collectors=report["collectors"] as Dictionary<string,object>;foreach(var pair in collectors){var c=pair.Value as Dictionary<string,object>;text.AppendLine("\n["+pair.Key+"] "+Agent.Get(c,"completedAt")+" · "+Agent.Get(c,"elapsedMs")+" мс · показателей: "+Agent.Get(c,"metricCount"));var rows=c["metrics"] as System.Collections.IEnumerable;foreach(var item in rows){var m=item as Dictionary<string,object>;text.AppendLine(Agent.Get(m,"state")+" · "+Agent.Get(m,"kind")+" · "+Agent.Get(m,"name")+" · "+Agent.Get(m,"source"));text.AppendLine("  "+Agent.Get(m,"measuredAt")+" · "+Agent.Get(m,"id")+" · "+Agent.Get(m,"reason"));text.AppendLine("  "+Agent.Json.Serialize(m["details"]));}}}catch(FileNotFoundException){text.AppendLine("Служба ещё не записала диагностику. Дождитесь первого опроса датчиков (SMART — до 15 минут).");}catch(Exception e){text.AppendLine("Снимок диагностики недоступен: "+e.GetType().Name);}
   foreach(string name in new[]{"diagnostics.log.3","diagnostics.log.2","diagnostics.log.1","diagnostics.log"})try{string path=Path.Combine(directory,name);if(File.Exists(path)){text.AppendLine("\n--- "+name+" ---");text.Append(ReadBounded(path,262144));}}catch(Exception e){text.AppendLine("Журнал недоступен: "+e.GetType().Name);}return text.ToString();
  }
  public static void ExportPublic(string root,string destination){using(var file=new FileStream(destination,FileMode.CreateNew,FileAccess.Write))using(var zip=new ZipArchive(file,ZipArchiveMode.Create)){using(var writer=new StreamWriter(zip.CreateEntry("diagnostics.txt").Open(),new UTF8Encoding(false)))writer.Write(Text(root));foreach(string name in new[]{"diagnostics.json","diagnostics.log","diagnostics.log.1","diagnostics.log.2","diagnostics.log.3"}){string path=Path.Combine(root,"public",name);if(!File.Exists(path))continue;using(var writer=new StreamWriter(zip.CreateEntry(name).Open(),new UTF8Encoding(false)))writer.Write(ReadBounded(path,name.EndsWith("json")?900000:262144));}using(var writer=new StreamWriter(zip.CreateEntry("README.txt").Open(),Encoding.UTF8))writer.Write("Локальная диагностика сборщиков. Конфигурация, пароли, токены, очередь метрик и исходные SMART-данные с серийными номерами не включены. Проверьте содержимое перед передачей.");}}
 }
}
